{"text":"[Reading 39 lines from start (total: 39 lines, 0 remaining)]\n\n\n\"\"\"\nGen AI Strategy Worker - LLM + RAG\nสร้างกลยุทธ์ใหม่ให้ลูกค้าเลือก\n\"\"\"\nimport random\n\nclass GenAIStrategyWorker:\n    def __init__(self, llm_api_key=None):\n        self.llm_api_key = llm_api_key\n        \n    def generate(self, market_regime, features, user_prompt):\n        prompt = f\"\"\"\n        คุณเป็น Quant AI สร้างกลยุทธ์เทรด\n        Market Regime: {market_regime}\n        Features: {features}\n        User wants: {user_prompt}\n        \n        สร้าง JSON กลยุทธ์ที่มี entry_workers เป็น Worker ตาม taxonomy:\n        - RSIWorker, VolumeSpikeWorker, GNN_CorrelationWorker, CNN_PatternWorker, FundingRateWorker, etc.\n        \"\"\"\n        # Mock LLM response\n        workers = random.sample(\n            [\"RSIWorker <35\", \"VolumeSpikeWorker\", \"GNN_CorrelationWorker\", \"CNN_PatternWorker\", \"FundingRateWorker\", \"WhaleFlowWorker\", \"Mamba_TrendWorker\"],\n            k=random.randint(2,4)\n        )\n        strategy = {\n            \"name\": f\"AI-Gen {random.choice(['Scalper','Swing','Hybrid'])} v{random.randint(1,9)}\",\n            \"entry_workers\": workers,\n            \"exit\": f\"TP {random.uniform(1,2.5):.1f}% / SL {random.uniform(0.5,1.2):.1f}%\",\n            \"reasoning\": f\"ใช้ {', '.join(workers)} เพราะ regime={market_regime}\",\n            \"prompt_used\": user_prompt\n        }\n        print(f\"🧠 LLM Generated: {strategy['name']} - Workers: {workers}\")\n        return strategy\n\nif __name__ == \"__main__\":\n    worker = GenAIStrategyWorker()\n    worker.generate(\"Bull\", {\"rsi\":30}, \"เน้นทำกำไรสั้น\")\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}